  if(building.level>=5){ctx.strokeStyle=building.level>=9?'#d3b765':'#697384';ctx.lineWidth=building.level>=7?3:2;ctx.beginPath();ctx.moveTo(pos.x-10,pos.y-height+8);ctx.lineTo(pos.x+10,pos.y-height+8);ctx.stroke();}
  if(building.level>=7){ctx.fillStyle='#3e5e8e';ctx.fillRect(pos.x-3,pos.y-height+11,6,12+building.level-7);ctx.fillStyle='#d4b361';ctx.fillRect(pos.x-1,pos.y-height+13,2,7);}
  if(building.level===10){ctx.strokeStyle='#d1b45f';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(pos.x,pos.y-height);ctx.lineTo(pos.x,pos.y-height-14);ctx.stroke();ctx.fillStyle='#365687';ctx.fillRect(pos.x,pos.y-height-13,8,6);}
